class _KembalianState extends State<Kembalian> {
  final _uang = TextEditingController();
  String hasil = '';

  @override
  void dispose() {
    _uang.dispose();
    super.dispose();
  }

  void hitung() {
    final uang = int.tryParse(_uang.text);
    setState(() {
      if (uang == null) {
        hasil = 'Masukkan angka saja';
      } else if (uang < widget.tagihan) {
        hasil = 'Uang kurang Rp${widget.tagihan - uang}';
      } else {
        hasil = 'Kembalian Rp${uang - widget.tagihan}';
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    return Column(children: [
      Text('Tagihan: Rp${widget.tagihan}'),
      TextField(
        controller: _uang,
        keyboardType: TextInputType.number,
        decoration: const InputDecoration(labelText: 'Uang dari pembeli'),
      ),
      FilledButton(onPressed: hitung, child: const Text('Hitung')),
      Text(hasil),
    ]);
  }
}

